package com.lolfm.simulator;import static org.assertj.core.api.Assertions.*;import com.lolfm.domain.Position;import org.junit.jupiter.api.Test;class ProgressionPowerEvaluatorTest{private PlayerState p(Position x){PlayerState p=new PlayerState("p",x,500);p.configureProgression(TeamSide.BLUE,true,new ProgressionExecutionStats());return p;}@Test void levelOneStartingHasZeroPower(){assertThat(new PlayerProgressionPowerEvaluator().evaluate(p(Position.TOP),ProgressionCombatContext.TEAMFIGHT,true).clampedTotalPower()).isZero();}@Test void levelAndItemPowerUseCommonFormula(){var p=p(Position.TOP);p.getProgressionState().awardExperience(ExperienceSource.KILL,2400,1);p.getProgressionState().awardEarnedGold(3500,GoldSource.KILL,1);var x=new PlayerProgressionPowerEvaluator().evaluate(p,ProgressionCombatContext.TEAMFIGHT,true);assertThat(x.levelPower()).isEqualTo(.6);assertThat(x.itemPower()).isEqualTo(.85);assertThat(x.clampedTotalPower()).isEqualTo(1.45);}@Test void everyPositionUsesIdenticalPower(){for(Position x:Position.values()){var p=p(x);p.getProgressionState().awardExperience(ExperienceSource.KILL,7300,1);p.getProgressionState().awardEarnedGold(7000,GoldSource.KILL,1);assertThat(new PlayerProgressionPowerEvaluator().evaluate(p,ProgressionCombatContext.TEAMFIGHT,true).clampedTotalPower()).isCloseTo(2.85,within(1e-9));}}@Test void championAndLevelSpikesRemainNeutral(){var p=p(Position.MID);p.getProgressionState().awardExperience(ExperienceSource.KILL,14700,1);var x=new PlayerProgressionPowerEvaluator().evaluate(p,ProgressionCombatContext.TEAMFIGHT,true);assertThat(x.championMultiplier()).isOne();assertThat(x.championSpikeBonus()).isZero();assertThat(x.levelPower()).isCloseTo(1.8,within(1e-9));}@Test void powerOffReturnsZeroContribution(){var p=p(Position.ADC);p.getProgressionState().awardExperience(ExperienceSource.KILL,18360,1);assertThat(new PlayerProgressionPowerEvaluator().evaluate(p,ProgressionCombatContext.TEAMFIGHT,false).clampedTotalPower()).isZero();}@Test void contextMultiplierAppliesToEdge(){GameState s=LateGameTestSupport.state();var p=s.getBlueTeamState().playerAt(Position.TOP);p.getProgressionState().awardExperience(ExperienceSource.KILL,2400,1);var x=new CombatProgressionEvaluator().evaluate(s,ProgressionCombatContext.LANE_COMBAT,java.util.List.of(p),java.util.List.of(s.getRedTeamState().playerAt(Position.TOP)));assertThat(x.finalContribution()).isEqualTo(x.progressionEdge()*.6);}}
